from pathlib import Path

p = Path('app/src/main/java/com/aracdefteri/app/ReceiptOcr.java')
s = p.read_text(encoding='utf-8')
for old,new in [
('import android.graphics.Bitmap;\n', 'import android.graphics.Bitmap;\nimport android.graphics.BitmapFactory;\nimport android.graphics.Canvas;\nimport android.graphics.ColorMatrix;\nimport android.graphics.ColorMatrixColorFilter;\nimport android.graphics.Paint;\n'),
('import java.io.IOException;\n', 'import java.io.IOException;\nimport java.io.InputStream;\n')]:
    if old not in s:
        raise SystemExit('import marker not found: '+old)
    s=s.replace(old,new,1)
old='''    private static void processImage(Context context, Uri imageUri, Callback callback) {\n        try {\n            InputImage image = InputImage.fromFilePath(context, imageUri);\n            TextRecognizer recognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);\n            recognizer.process(image)\n                    .addOnSuccessListener(text -> {\n                        try {\n                            if (text == null || text.getText().trim().isEmpty()) {\n                                callback.onError(new IOException(\"Belgede okunabilir metin bulunamadı\"));\n                            } else {\n                                callback.onResult(RecordParser.fromText(text.getText()));\n                            }\n                        } finally {\n                            recognizer.close();\n                        }\n                    })\n                    .addOnFailureListener(error -> {\n                        try { callback.onError(error); }\n                        finally { recognizer.close(); }\n                    });\n        } catch (IOException e) {\n            callback.onError(e);\n        }\n    }\n'''
new='''    private static void processImage(Context context, Uri imageUri, Callback callback) {\n        try {\n            InputImage image = InputImage.fromFilePath(context, imageUri);\n            TextRecognizer recognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);\n            recognizer.process(image)\n                    .addOnSuccessListener(text -> {\n                        String original = text == null ? \"\" : text.getText().trim();\n                        // Fiş/gösterge fotoğraflarında küçük LCD ve termal yazılar ilk geçişte\n                        // kaçabiliyor. İkinci, yüksek kontrastlı geçişi birleştiriyoruz.\n                        processEnhancedImage(context, imageUri, recognizer, original, callback);\n                    })\n                    .addOnFailureListener(error -> {\n                        try { callback.onError(error); }\n                        finally { recognizer.close(); }\n                    });\n        } catch (IOException e) {\n            callback.onError(e);\n        }\n    }\n\n    private static void processEnhancedImage(Context context, Uri imageUri, TextRecognizer recognizer,\n                                             String originalText, Callback callback) {\n        Bitmap source = null;\n        Bitmap scaled = null;\n        Bitmap enhanced = null;\n        try {\n            try (InputStream in = context.getContentResolver().openInputStream(imageUri)) {\n                source = BitmapFactory.decodeStream(in);\n            }\n            if (source == null) {\n                finishImageRecognition(recognizer, originalText, \"\", callback);\n                return;\n            }\n            int maxWidth = 2000;\n            if (source.getWidth() > maxWidth) {\n                int h = Math.max(1, Math.round(source.getHeight() * (maxWidth / (float) source.getWidth())));\n                scaled = Bitmap.createScaledBitmap(source, maxWidth, h, true);\n            } else {\n                scaled = source;\n            }\n            enhanced = Bitmap.createBitmap(scaled.getWidth(), scaled.getHeight(), Bitmap.Config.ARGB_8888);\n            Canvas canvas = new Canvas(enhanced);\n            Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.FILTER_BITMAP_FLAG);\n            ColorMatrix saturation = new ColorMatrix();\n            saturation.setSaturation(0f);\n            ColorMatrix contrast = new ColorMatrix(new float[]{\n                    1.75f,0,0,0,-95,\n                    0,1.75f,0,0,-95,\n                    0,0,1.75f,0,-95,\n                    0,0,0,1,0\n            });\n            saturation.postConcat(contrast);\n            paint.setColorFilter(new ColorMatrixColorFilter(saturation));\n            canvas.drawBitmap(scaled, 0, 0, paint);\n\n            final Bitmap finalEnhanced = enhanced;\n            final Bitmap finalSource = source;\n            final Bitmap finalScaled = scaled;\n            recognizer.process(InputImage.fromBitmap(finalEnhanced, 0))\n                    .addOnSuccessListener(text -> {\n                        String enhancedText = text == null ? \"\" : text.getText().trim();\n                        recycle(finalEnhanced, finalScaled, finalSource);\n                        finishImageRecognition(recognizer, originalText, enhancedText, callback);\n                    })\n                    .addOnFailureListener(error -> {\n                        recycle(finalEnhanced, finalScaled, finalSource);\n                        finishImageRecognition(recognizer, originalText, \"\", callback);\n                    });\n        } catch (Exception e) {\n            recycle(enhanced, scaled, source);\n            finishImageRecognition(recognizer, originalText, \"\", callback);\n        }\n    }\n\n    private static void finishImageRecognition(TextRecognizer recognizer, String original, String enhanced, Callback callback) {\n        try {\n            String combined;\n            if (original == null) original = \"\";\n            if (enhanced == null) enhanced = \"\";\n            if (original.trim().isEmpty()) combined = enhanced.trim();\n            else if (enhanced.trim().isEmpty() || enhanced.trim().equals(original.trim())) combined = original.trim();\n            else combined = original.trim() + \"\\n--- IKINCI OKUMA ---\\n\" + enhanced.trim();\n            if (combined.isEmpty()) callback.onError(new IOException(\"Belgede okunabilir metin bulunamadı\"));\n            else callback.onResult(RecordParser.fromText(combined));\n        } finally {\n            recognizer.close();\n        }\n    }\n\n    private static void recycle(Bitmap enhanced, Bitmap scaled, Bitmap source) {\n        if (enhanced != null && !enhanced.isRecycled()) enhanced.recycle();\n        if (scaled != null && scaled != source && !scaled.isRecycled()) scaled.recycle();\n        if (source != null && !source.isRecycled()) source.recycle();\n    }\n'''
if old not in s:
    raise SystemExit('processImage block not found')
s=s.replace(old,new,1)
p.write_text(s,encoding='utf-8')

# Table-style receipt values can be one or two lines below the label.
p = Path('app/src/main/java/com/aracdefteri/app/SmartDocumentAnalyzer.java')
s = p.read_text(encoding='utf-8')
old='''    private static double labelledDecimal(String raw, String[] labels) {\n        String[] lines=raw.split(\"\\\\r?\\\\n\"); Pattern num=Pattern.compile(\"([0-9]{1,7}(?:[.,][0-9]{1,3})?)\");\n        for(String line:lines){String n=normalize(line); boolean ok=false; for(String label:labels) if(n.contains(normalize(label))){ok=true;break;} if(!ok) continue; Matcher m=num.matcher(line); while(m.find()){double v=dec(m.group(1)); if(v>0) return v;}}\n        return 0;\n    }\n'''
new='''    private static double labelledDecimal(String raw, String[] labels) {\n        String[] lines=raw.split(\"\\\\r?\\\\n\"); Pattern num=Pattern.compile(\"([0-9]{1,7}(?:[.,][0-9]{1,3})?)\");\n        for(int i=0;i<lines.length;i++){String n=normalize(lines[i]); boolean ok=false; for(String label:labels) if(n.contains(normalize(label))){ok=true;break;} if(!ok) continue; for(int j=i;j<=Math.min(i+2,lines.length-1);j++){Matcher m=num.matcher(lines[j]); while(m.find()){double v=dec(m.group(1)); if(v>0) return v;}}}\n        return 0;\n    }\n'''
if old not in s:
    raise SystemExit('labelledDecimal block not found')
s=s.replace(old,new,1)
# Give actual fuel-station brands stronger evidence even if OCR misses LT label.
old='''        if (!knownVendor(n).isEmpty()) score += 2;'''
new='''        if (!knownVendor(n).isEmpty()) score += 2;\n        if (isFuelVendor(n)) score += 3;'''
if old not in s:
    raise SystemExit('knownVendor evidence marker not found')
s=s.replace(old,new,1)
marker='''    private static String knownVendor(String n) {'''
helper='''    private static boolean isFuelVendor(String n) {\n        return containsAny(n, \"shell\", \"opet\", \"petrol ofisi\", \"totalenergies\", \"total energies\", \"bp\", \"aytemiz\", \"alpet\", \"turkiye petrolleri\", \"tp petrol\", \"kadoil\", \"sunpet\", \"socar\", \"lukoil\", \"moil\", \"termo\");\n    }\n\n'''
if marker not in s:
    raise SystemExit('knownVendor marker not found')
s=s.replace(marker,helper+marker,1)
p.write_text(s,encoding='utf-8')

p = Path('app/build.gradle')
s = p.read_text(encoding='utf-8')
import re
s = re.sub(r'versionCode\s+\d+', 'versionCode 17', s, count=1)
s = re.sub(r"versionName\s+'[^']+'", "versionName '0.13.1-enhanced-ocr-dev'", s, count=1)
p.write_text(s,encoding='utf-8')
